package main
import("fmt";"net/http";"net/http/httptest";"strings";"github.com/gorilla/websocket")
func main(){cases:=[]struct{name string;origins []string;defaultCode,candidateCode int}{{"absent",nil,101,101},{"same-host",[]string{"http://k.local"},101,101},{"ASCII-case",[]string{"http://K.LOCAL"},101,101},{"exact-Tauri",[]string{"http://tauri.localhost"},403,101},{"unrelated",[]string{"http://other.local"},403,403},{"lookalike",[]string{"http://tauri.localhost.evil"},403,403},{"Kelvin",[]string{"http://K.local"},403,403},{"multiple-Tauri",[]string{"http://tauri.localhost","http://evil.local"},403,403},{"non-exact-Tauri",[]string{"HTTP://tauri.localhost"},403,403}};for _,c:=range cases{for _,candidate:=range []bool{false,true}{srv:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){r.Host="k.local";upgrader:=websocket.Upgrader{};if candidate{origins:=r.Header["Origin"];if len(origins)==1&&origins[0]=="http://tauri.localhost"{upgrader.CheckOrigin=func(*http.Request)bool{return true}}};ws,err:=upgrader.Upgrade(w,r,nil);if err==nil{ws.Close()}}));headers:=http.Header{};if c.origins!=nil{headers["Origin"]=c.origins};ws,res,err:=websocket.DefaultDialer.Dial("ws"+strings.TrimPrefix(srv.URL,"http"),headers);if ws!=nil{ws.Close()};code:=0;if res!=nil{code=res.StatusCode;res.Body.Close()};srv.Close();want:=c.defaultCode;if candidate{want=c.candidateCode};fmt.Printf("case=%s candidate=%v status=%d expected=%d error=%v\n",c.name,candidate,code,want,err);if code!=want{panic("unexpected admission")}}};fmt.Println("PASS locked Gorilla v1.5.3 18 handshake controls; only exact Tauri admission changes. Proposal probe only, no Gateway implementation/auth-bind acceptance.")}
